    Bug 1980800 - Add migration code to maintain user sort order of newsgroup folders. r=babolivier

    Differential Revision: https://phabricator.services.mozilla.com/D259692

diff --git a/mail/modules/MailMigrator.sys.mjs b/mail/modules/MailMigrator.sys.mjs
index c08f202753a..b5b518ec19e 100644
--- a/mail/modules/MailMigrator.sys.mjs
+++ b/mail/modules/MailMigrator.sys.mjs
@@ -29,7 +29,7 @@ export var MailMigrator = {
   _migrateUI() {
     // The code for this was ported from
     // mozilla/browser/components/nsBrowserGlue.js
-    const UI_VERSION = 51;
+    const UI_VERSION = 52;
     const UI_VERSION_PREF = "mail.ui-rdf.version";
     let currentUIVersion = Services.prefs.getIntPref(UI_VERSION_PREF, 0);

@@ -285,6 +285,21 @@ export var MailMigrator = {
         }
       }

+      if (currentUIVersion < 52) {
+        // Preset the user sort order of all NNTP folders in a way so that they
+        // keep their existing order.
+        MailServices.accounts.accounts
+          .filter(a => a.incomingServer.type == "nntp")
+          .forEach(a => {
+            const folders = MailServices.folderLookup.getFolderForURL(
+              a.incomingServer.serverURI
+            ).subFolders;
+            for (let i = 0; i < folders.length; i++) {
+              folders[i].userSortOrder = i + 1;
+            }
+          });
+      }
+
       // Migration tasks that may take a long time are not run immediately, but
       // added to the MigrationTasks object then run at the end.
       //
